python3 - <<'PY'
from pathlib import Path
p = Path('test/ranges-test.cc')
s = p.read_text()
old = '#include "gtest/gtest.h"\n'
new = '''#include "gtest/gtest.h"

#ifdef __cpp_lib_ranges
#  include <ranges>
#endif
'''
assert s.count(old) == 1
s = s.replace(old, new)
s += '''
#ifdef __cpp_lib_ranges
TEST(ranges_test, split_view) {
  auto line = std::string("a,b-c,d-e,f");
  EXPECT_EQ(fmt::format("{}", line | std::views::split(',')),
            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
}

struct non_const_string_view {
  std::string_view str;

  template <std::ranges::contiguous_range R>
  explicit non_const_string_view(R&& range)
      : str(std::ranges::data(range), std::ranges::size(range)) {}

  auto begin() { return str.begin(); }
  auto end() { return str.end(); }
};

TEST(ranges_test, transform_non_const_range) {
  auto line = std::string("a,b-c,d-e,f");
  auto range = line | std::views::split(',') |
               std::views::transform([](auto part) {
                 return non_const_string_view(part);
               });
  EXPECT_EQ(fmt::format("{}", range),
            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
  EXPECT_EQ(fmt::format("{:::}", range), "[[a], [b, -, c], [d, -, e], [f]]");
}

TEST(ranges_test, transform_split_view) {
  auto line = std::string("a,b-c,d-e,f");
  auto range = line | std::views::split(',') |
               std::views::transform(std::views::split('-'));
  EXPECT_EQ(fmt::format("{}", range),
            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
}
#endif
'''
p.write_text(s)
