python3 - <<'PY'
from pathlib import Path
p = Path('include/fmt/ranges.h')
s = p.read_text()
old = '''    if (it == end || *it == '}') {
      maybe_set_debug_format();
      return it;
    }

    if (*it == 'n') {
      set_brackets({}, {});
      ++it;
    }

    if (*it == '}') {
      maybe_set_debug_format();
      return it;
    }
'''
new = '''    if (it != end && *it == 'n') {
      set_brackets({}, {});
      ++it;
    }

    if (it == end || *it == '}') {
      ctx.advance_to(it);
      maybe_set_debug_format();
      return underlying_.parse(ctx);
    }
'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))
p = Path('test/ranges-test.cc')
s = p.read_text()
s += '''
TEST(ranges_test, nested_char_ranges) {
  auto range = std::vector<std::vector<char>>{{'a', '\\n'}, {'\\'', '\\\\'}};
  EXPECT_EQ(fmt::format("{}", range), "[['a', '\\\\n'], ['\\\\\\'', '\\\\\\\\']]");
  EXPECT_EQ(fmt::format("{:n}", range), "['a', '\\\\n'], ['\\\\\\'', '\\\\\\\\']");
  EXPECT_EQ(fmt::format("{::n}", range), "['a', '\\\\n', '\\\\\\'', '\\\\\\\\']");
  auto strings = std::vector<std::vector<std::string>>{{"a", "b"}, {"c"}};
  EXPECT_EQ(fmt::format("{}", strings), "[[\\"a\\", \\"b\\"], [\\"c\\"]]");
  EXPECT_EQ(fmt::format("{:::}", strings), "[[a, b], [c]]");
}
'''
p.write_text(s)
p = Path('ChangeLog.rst')
s = p.read_text()
old = '''* Fixed formatting of ranges whose iterators return temporary ranges that
  only support non-const iteration.
'''
new = '''* Fixed formatting of ranges whose iterators return temporary ranges that
  only support non-const iteration, and debug formatting of nested character
  and string ranges.
'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))
